package com.hmdp.ai.domain.tool;
import com.fasterxml.jackson.databind.JsonNode;import com.hmdp.ai.domain.artifact.ArtifactReference;import com.hmdp.ai.domain.artifact.Citation;import com.hmdp.ai.domain.run.UsageSummary;import java.util.*;
public final class ToolResult {private final ToolCallStatus status;private final JsonNode data;private final List<Citation> citations;private final List<ArtifactReference> artifacts;private final List<String>warnings;private final UsageSummary usage;private final String errorCode,errorMessage;private final boolean retryable;public ToolResult(ToolCallStatus status,JsonNode data,List<Citation>citations,List<ArtifactReference>artifacts,List<String>warnings,UsageSummary usage,String errorCode,String errorMessage,boolean retryable){this.status=status;this.data=data;this.citations=Collections.unmodifiableList(new ArrayList<>(citations==null?Collections.emptyList():citations));this.artifacts=Collections.unmodifiableList(new ArrayList<>(artifacts==null?Collections.emptyList():artifacts));this.warnings=Collections.unmodifiableList(new ArrayList<>(warnings==null?Collections.emptyList():warnings));this.usage=usage;this.errorCode=errorCode;this.errorMessage=errorMessage;this.retryable=retryable;}public static ToolResult success(JsonNode data,long ms){return success(data,Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),UsageSummary.empty(ms));}public static ToolResult success(JsonNode data,List<Citation>citations,List<ArtifactReference>artifacts,List<String>warnings,UsageSummary usage){return new ToolResult(ToolCallStatus.SUCCEEDED,data,citations,artifacts,warnings,usage,null,null,false);}public static ToolResult failure(ToolCallStatus s,String c,String m,boolean r){return new ToolResult(s,null,Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),UsageSummary.empty(0),c,m,r);}public ToolCallStatus getStatus(){return status;}public JsonNode getData(){return data;}public List<Citation>getCitations(){return citations;}public List<ArtifactReference>getArtifacts(){return artifacts;}public List<String>getWarnings(){return warnings;}public UsageSummary getUsage(){return usage;}public String getErrorCode(){return errorCode;}public String getErrorMessage(){return errorMessage;}public boolean isRetryable(){return retryable;}}
